<script module lang="ts">
/**
 * A score as a row of marks (`design/components/rating.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/rating.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import {
  Icon,
  agentMember,
  joinSlot,
  ratingModel,
  ratingPress,
  roveRating,
  watchEffect,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/controls/rating.module.css'

export type RatingSize = NonNullable<RatingProps['size']>

export interface RatingMessages {
  /** A mark's name, from the value it sets and that value's numeral: "3 stars". */
  mark: (value: number, numeral: string) => string
  /** The shown rating's name, one sentence: "Rating: 4.3 out of 5". */
  shown: (label: string, value: string, max: string) => string
}

export interface RatingProps {
  'aria-describedby'?: string
  /**
   * Wired by FormField, which names the group with its label.
   */
  'aria-labelledby'?: string
  /**
   * A required rating cannot be cleared by a press.
   */
  'aria-required'?: boolean
  defaultValue?: number | null
  disabled?: boolean
  id?: string
  invalid?: boolean
  /**
   * The rating's name. A control's group is named by it ("Rate this answer") unless a FormField
   * names it, and a shown rating's sentence starts with it ("Average rating").
   */
  label: string
  /**
   * Writes the numerals of the marks' names and the shown sentence. Defaults to the page's own.
   */
  locale?: string
  /**
   * The number of marks: a whole number from 2 to 10. Default 5.
   */
  max?: number
  messages?: RatingMessages
  /**
   * Posts the value as a whole number, or nothing when the rating holds none.
   */
  name?: string
  /**
   * The value a press or a key chose, or `null` when a press cleared it. Never called for a
   * shown rating.
   */
  onChange?: (value: number | null) => void
  /**
   * Shows the rating as an image a reader reads and cannot change.
   */
  readOnly?: boolean
  /**
   * The marks' size: the icon sizes. A control's hit targets stay one size.
   */
  size?: 'sm' | 'md' | 'lg'
  /**
   * What the rating holds. A control holds a whole number from 1 to `max`, or `null` for no
   * rating. A shown rating holds any value from 0 to `max`, drawn to one decimal place.
   */
  value?: number | null
}

export const controlKind = 'group'
</script>

<script lang="ts">
let {
  'aria-describedby': ariaDescribedbyOwn,
  'aria-labelledby': ariaLabelledbyOwn,
  'aria-required': ariaRequiredOwn,
  defaultValue,
  disabled = false,
  id: idOwn,
  invalid: invalidOwn = false,
  label: labelOwn,
  locale,
  max,
  messages,
  name,
  onChange,
  readOnly = false,
  size = 'md',
  value,
}: RatingProps = $props()
const joined = joinSlot(controlKind, () => ({
  disabled: disabled,
  label: labelOwn,
  name: name,
  size: size,
}))
const ariaDescribedby = $derived(
  joined.passed['aria-describedby'] === undefined
    ? ariaDescribedbyOwn
    : (joined.passed['aria-describedby'] as typeof ariaDescribedbyOwn),
)
const ariaLabelledby = $derived(
  joined.passed['aria-labelledby'] === undefined
    ? ariaLabelledbyOwn
    : (joined.passed['aria-labelledby'] as typeof ariaLabelledbyOwn),
)
const ariaRequired = $derived(
  joined.passed['aria-required'] === undefined
    ? ariaRequiredOwn
    : (joined.passed['aria-required'] as typeof ariaRequiredOwn),
)
const id = $derived(
  joined.passed['id'] === undefined ? idOwn : (joined.passed['id'] as typeof idOwn),
)
const invalid = $derived(
  joined.passed['invalid'] === undefined
    ? invalidOwn
    : (joined.passed['invalid'] as typeof invalidOwn),
)
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
// svelte-ignore state_referenced_locally
let mirror = $state(defaultValue ?? null)
let root = $state<HTMLElement | null>(null)
const model = $derived(
  ratingModel({
    value: value === undefined ? mirror : value,
    label,
    max,
    readOnly,
    locale,
    messages,
  }),
)
const settle = $derived(
  (next: number | null) => next !== model.value && ((mirror = next), onChange?.(next), true),
)
const stop = $derived(model.value ?? 1)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'Rating',
    element: () => root,
    state: () => ({
      value: model.value,
      max: model.max,
      readonly: readOnly,
      disabled: disabled,
      invalid: invalid,
    }),
    actions: {
      set: {
        argument: 'number',
        run: (value) =>
          (() => {
            if (readOnly) throw new Error('The rating is shown and takes no press.')
            if (!Number.isInteger(value) || value < 1 || value > model.max) {
              throw new Error(`A rating is a whole number from 1 to ${model.max}.`)
            }
            settle(value)
          })(),
      },
      clear: () =>
        (() => {
          if (readOnly) throw new Error('The rating is shown and takes no press.')
          if (ariaRequired === true) throw new Error('A required rating keeps its mark.')
          settle(null)
        })(),
    },
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }{#if readOnly
    }<span
      bind:this={root}
      class={styles.rating}
      {id}
      role="img"
      aria-label={model.sentence}
      aria-describedby={ariaDescribedby}
      data-size={size}
      data-readonly=""
      data-member="rating"
      >{#each model.marks as mark (mark.value)
        }<span class={styles.mark} data-fill={mark.fill}
          ><span class={styles.glyph}
            ><Icon name="rating" {size}
            /><span class={styles.fill} style:inline-size={mark.share}
              ><Icon name="rating" {size}
            /></span
          ></span
        ></span
      >{/each
      }{#if name !== undefined
        }<input
          type="hidden"
          {name}
          value={model.value === null ? '' : String(model.value)}
          disabled={disabled && !readOnly}
      />{/if
    }</span
  >{:else
    }<span
      bind:this={root}
      class={styles.rating}
      {id}
      role="radiogroup"
      aria-label={label}
      aria-labelledby={ariaLabelledby}
      aria-describedby={ariaDescribedby}
      aria-required={(ariaRequired === true) ? true : undefined}
      aria-invalid={(invalid) ? true : undefined}
      data-size={size}
      data-disabled={(disabled) ? '' : undefined}
      data-invalid={(invalid) ? '' : undefined}
      data-member="rating"
      >{#each model.marks as mark (mark.value)
        }<button
          class={styles.mark}
          type="button"
          role="radio"
          aria-checked={mark.value === model.value}
          aria-label={mark.name}
          {disabled}
          tabindex={(mark.value === stop ? 0 : -1) as never}
          data-fill={mark.fill}
          onclick={() => { settle(ratingPress(mark.value, model.value, ariaRequired === true)) }}
          onkeydown={(event) => { roveRating(event, settle) }}
          ><span class={styles.glyph}
            ><Icon name="rating" {size}
            /><span class={styles.fill} style:inline-size={mark.share}
              ><Icon name="rating" {size}
            /></span
          ></span
        ></button
      >{/each
      }{#if name !== undefined
        }<input
          type="hidden"
          {name}
          value={model.value === null ? '' : String(model.value)}
          disabled={disabled && !readOnly}
      />{/if
    }</span
  >{/if
}{/if
}{@render joined.end?.()}
